{
  "name": "@mixio-pro/mixiocode-plugin",
  "version": "0.1.1",
  "description": "OpenCode plugin that auto-commits changes after every session run.",
  "module": "src/index.ts",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "git",
    "auto-commit"
  ],
  "author": "Kaustubh Agrawal",
  "license": "MIT",
  "scripts": {
    "dev": "bun run --watch src/index.ts",
    "build": "bun build src/index.ts --outdir dist --target bun",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "clean": "rm -rf dist",
    "prepublishOnly": "bun run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/bun": "latest"
  },
  "peerDependencies": {
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@google-cloud/storage": "^7.19.0",
    "zod": "^4.3.6"
  }
}
